import java.util.Arrays;
import java.util.Scanner;

public class Main {
    static final long MOD_A = 998244353;
    static final long MOD_B = 1000000007;
    static final int MAXN = 1000000;

    static long total, limit, counter;
    static int result;
    static int[] digit_counts = new int[7];
    static int[][][] array_counts = new int[7][7][];
    static long[][][] sum_storage = new long[7][7][];

    static Scanner scanner = new Scanner(System.in);

    static void build(int x, int depth, int max_depth) {
        array_counts[max_depth][depth] = ensureCapacity(array_counts[max_depth][depth], ++counter);
        sum_storage[max_depth][depth][array_counts[max_depth][depth] - 1] = (++counter) - x;
        if (depth == max_depth) return;
        for (int i = 0; i <= 9; ++i) {
            build(x * 10 + i, depth + 1, max_depth);
        }
    }

    static void brute(long x, int depth) {
        if (x > total) return;
        ++counter;
        result = (int)((result + (counter - x) / MOD_A - (counter < x ? 1 : 0) + MOD_B) % MOD_B);
        for (int i = 0; i <= 9; ++i) {
            brute(x * 10 + i, depth + 1);
        }
    }

    static void process(int x, int depth) {
        if (depth != 6) {
            ++counter;
            result = (int)((result + (counter - x) / MOD_A - (counter < x ? 1 : 0) + MOD_B) % MOD_B);
            for (int i = 0; i <= 9; ++i) {
                process(x * 10 + i, depth + 1);
            }
            return;
        }
        if (x == limit) return;
        int k = 0;
        long v = x;
        while (k <= 6 && v <= total) {
            v *= 10;
            k++;
        }
        k--;
        for (int i = 0; i <= k; ++i) {
            v = counter - 1L * x * digit_counts[i];
            long temp = (v / MOD_A - (v < 0 ? 1 : 0) + MOD_B) % MOD_B;
            result = (int)((result + temp * digit_counts[i]) % MOD_B);
            v = ((v % MOD_A) + MOD_A) % MOD_A;
            int idx = lowerBound(sum_storage[k][i], 0, digit_counts[i], v);
            result = (int)((result + digit_counts[i] - (idx - 1 >= 0 ? sum_storage[k][i][idx - 1] : 0) + MOD_B) % MOD_B);
        }
        for (int i = 0; i <= k; ++i) {
            counter += digit_counts[i];
        }
    }

    public static void main(String[] args) {
        total = scanner.nextLong();
        digit_counts[0] = 1;
        for (int k = 1; k <= 6; ++k) {
            digit_counts[k] = digit_counts[k - 1] * 10;
        }
        for (int k = 0; k <= 6; ++k) {
            counter = 0;
            for (int i = 0; i < 7; ++i) {
                array_counts[k][i] = new int[0];
                sum_storage[k][i] = new long[0];
            }
            for (int i = 0; i <= k; ++i) {
                array_counts[k][i] = new int[1];
                sum_storage[k][i] = new long[digit_counts[i]];
            }
            for (int i = 0; i <= k; ++i) {
                Arrays.fill(sum_storage[k][i], 0);
            }
            build(0, 0, k);
            for (int i = 0; i <= k; ++i) {
                Arrays.sort(sum_storage[k][i], 0, digit_counts[i]);
            }
        }
        counter = 0;
        if (counter == 0 && total < 1e6) {
            for (int i = 1; i <= 9; ++i) {
                brute(i, 1);
            }
        } else {
            limit = total;
            while (limit >= 1e6) limit /= 10;
            for (int i = 1; i <= 9; ++i) {
                process(i, 1);
            }
        }
        System.out.println((int)((1L * (MOD_B - result) * MOD_A) % MOD_B));
    }

    static int lowerBound(long[] arr, int start, int end, long target) {
        int low = start;
        int high = end;
        while (low < high) {
            int mid = (low + high) / 2;
            if (arr[mid] < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    static int[] ensureCapacity(int[] arr, long size) {
        if (arr.length >= size) return arr;
        int[] newArr = new int[(int)size];
        System.arraycopy(arr, 0, newArr, 0, arr.length);
        return newArr;
    }
}
